import{_ as a,c as n,aU as e,a as i}from"./chunks/framework.DIXiA2XH.js";const g=JSON.parse('{"title":"配置文件","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/java-spring/07-配置文件.md","filePath":"note/back-end/java-spring/07-配置文件.md","lastUpdated":1774795644000}'),r={name:"note/back-end/java-spring/07-配置文件.md"};function l(p,s,t,o,d,c){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h1><h2 id="动态导入配置文件" tabindex="-1">动态导入配置文件 <a class="header-anchor" href="#动态导入配置文件" aria-label="Permalink to &quot;动态导入配置文件&quot;">​</a></h2><p>在Spring Boot 2.4及以后的版本中，引入了一种新的方式来导入额外的配置，通过<code>spring.config.import</code>属性。这个属性允许我们在<code>application.properties</code>或<code>application.yml</code>中声明要导入的配置文件。</p><p>这个配置 spring.config.import=<code>optional:file:.env[.properties]</code> 是 Spring Boot 2.4+ 引入的新特性，用于动态导入配置文件。下面详细解释其含义和作用：</p><h3 id="配置语法解析" tabindex="-1"><strong>配置语法解析</strong> <a class="header-anchor" href="#配置语法解析" aria-label="Permalink to &quot;**配置语法解析**&quot;">​</a></h3><ul><li><code>optional:file:.env[.properties]</code> 可拆解为三部分： <ul><li><strong><code>optional:</code></strong><br> 表示文件是可选的。如果 <code>.env</code> 文件不存在，<strong>应用不会报错</strong>，会正常启动（忽略缺失的文件）。</li><li><strong><code>file:</code></strong><br> 表示从<strong>文件系统</strong>（而非 classpath）加载文件。默认从<strong>项目根目录</strong>（工作目录）查找文件。</li><li><strong><code>.env[.properties]</code></strong><ul><li><code>.env</code>：要加载的文件名（无后缀）。</li><li><code>[.properties]</code>：显式指定文件格式为 <strong>Properties 格式</strong>（键值对）。<br><em>即使文件没有后缀，也会按 <code>.properties</code> 语法解析。</em></li></ul></li></ul></li></ul><h3 id="实际效果" tabindex="-1"><strong>实际效果</strong> <a class="header-anchor" href="#实际效果" aria-label="Permalink to &quot;**实际效果**&quot;">​</a></h3><ul><li><strong>加载根目录下的 <code>.env</code> 文件</strong><br> Spring Boot 会尝试从<strong>项目启动时的当前工作目录</strong>（通常是项目根目录）加载 <code>.env</code> 文件。</li><li><strong>解析为 Properties 格式</strong><br> 文件内容会被解析为标准 Properties 格式（示例）：<div class="language-properties vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=jdbc:mysql://localhost:3306/mydb</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=root</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DB_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=123456</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><strong>注入到 Spring Environment</strong><br> 文件中的配置（如 <code>DB_URL</code>）会并入 Spring 环境变量，可通过 <code>@Value(&quot;\${DB_URL}&quot;)</code> 或 <code>Environment</code> 对象获取。</li></ul><h3 id="为什么需要这样配置" tabindex="-1"><strong>为什么需要这样配置？</strong> <a class="header-anchor" href="#为什么需要这样配置" aria-label="Permalink to &quot;**为什么需要这样配置？**&quot;">​</a></h3><ul><li><strong>突破默认规则</strong><br> Spring Boot 默认只加载 <code>application.properties</code>/<code>application.yml</code> 和 <code>application-{profile}.properties</code>。<br> 此配置让非标准文件名（如 <code>.env</code>）也能被加载。</li><li><strong>环境隔离</strong><br> 将敏感配置（如数据库密码）从主配置分离到 <code>.env</code> 文件，便于通过 <code>.gitignore</code> 排除（避免提交到仓库）。</li><li><strong>兼容性</strong><br> 许多工具（如 Docker）默认支持 <code>.env</code> 文件，方便与现有 DevOps 流程集成。</li></ul><h3 id="典型使用场景" tabindex="-1"><strong>典型使用场景</strong> <a class="header-anchor" href="#典型使用场景" aria-label="Permalink to &quot;**典型使用场景**&quot;">​</a></h3><h4 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-project/</span></span>
<span class="line"><span>├── .env                # 存放敏感配置（被 .gitignore 排除）</span></span>
<span class="line"><span>├── application.properties  # 主配置文件</span></span>
<span class="line"><span>└── src/</span></span>
<span class="line"><span>    └── main/...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="配置示例" tabindex="-1">配置示例 <a class="header-anchor" href="#配置示例" aria-label="Permalink to &quot;配置示例&quot;">​</a></h4><ul><li><strong><code>.env</code> 文件内容</strong><div class="language-properties vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SPRING_DATASOURCE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=jdbc:mysql://localhost:3306/mydb</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SPRING_DATASOURCE_USERNAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=admin</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SPRING_DATASOURCE_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=secret</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><strong><code>application.properties</code> 内容</strong><div class="language-properties vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 导入 .env 文件</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.config.import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=optional:file:.env[.properties]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用 .env 中的变量</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.datasource.url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=\${SPRING_DATASOURCE_URL}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.datasource.username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=\${SPRING_DATASOURCE_USERNAME}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.datasource.password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=\${SPRING_DATASOURCE_PASSWORD}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div></li></ul><hr>`,16)])])}const b=a(r,[["render",l]]);export{g as __pageData,b as default};
